x_938076_backup_0_backup_scripts.script:
WPLogger.info('migrateRoleRuleConfig', 'Started: Migration of Workplace role rule configuration');
migrateRoleRuleConfig();

function migrateRoleRuleConfig() {
    var roleConfigGr = new GlideRecord(WPConstants.TABLES.CLIENT_ROLE);
    if (roleConfigGr.isValid() && roleConfigGr.isValidField('country')) {
        roleConfigGr.setWorkflow(false);
        roleConfigGr.query();
        while (roleConfigGr.next() && (!gs.nil(roleConfigGr.country) && (gs.nil(roleConfigGr.table) || gs.nil(roleConfigGr.condition)))) {
			WPLogger.info('migrateRoleRuleConfig', 'Migrating '+roleConfigGr.name);
            roleConfigGr.table = WPConstants.COMMON_TABLES.SYS_USER;
            roleConfigGr.condition = "location.country=" + roleConfigGr.country + "^EQ";
            roleConfigGr.update();
        }

		WPLogger.info('migrateRoleRuleConfig', 'Starting migration of Scheduled job "Add or Remove WSD User role"');
        var schJobGr = new GlideRecord(WPConstants.COMMON_TABLES.SCHEDULED_JOB);
        if (schJobGr.get("5c05b9100f751010784dd2d92f767ecb") && schJobGr.active) {
			WPLogger.info('migrateRoleRuleConfig', 'Disabling Scheduled job - "Add or Remove WSD User role"');
            schJobGr.active = false;
            schJobGr.update();
        }
    }
	WPLogger.info('migrateRoleRuleConfig', 'Completed: Migration of Workplace role rule configuration');
}
